<script lang="ts">
	import { toast } from 'svelte-sonner';

	import { tick, getContext, onMount, createEventDispatcher } from 'svelte';
	const dispatch = createEventDispatcher();
	const i18n = getContext('i18n');

	import { settings } from '$lib/stores';
	import { gisPortalVisible } from '$lib/components/gis-portal/stores';
	import { copyToClipboard } from '$lib/utils';

	import MultiResponseMessages from './MultiResponseMessages.svelte';
	import ResponseMessage from './ResponseMessage.svelte';
	import UserMessage from './UserMessage.svelte';

	export let chatId;
	export let selectedModels = [];
	export let idx = 0;

	export let history;
	export let messageId;

	export let user;

	export let setInputText: Function = () => {};
	export let gotoMessage;
	export let showPreviousMessage;
	export let showNextMessage;
	export let updateChat;

	export let editMessage;
	export let saveMessage;
	export let deleteMessage;
	export let rateMessage;
	export let actionMessage;
	export let submitMessage;

	export let regenerateResponse;
	export let continueResponse;
	export let mergeResponses;

	export let addMessages;
	export let onToolCallResolved: Function = () => {};
	export let forkHandler: Function | null = null;
	export let triggerScroll;
	export let readOnly = false;
	export let shareMode: 'continue' | null = null;
	export let allowDelete = true;
	export let allowToolApproval: boolean = false;
	export let compactPreview = false;
	export let editCodeBlock = true;
	export let topPadding = false;
	export let onInsertToNote: ((content: string) => void) | null = null;

	// Keep the latest turn's real height when assigning a chat ID remounts the message list.
	$: isCurrentTurn =
		messageId === history.currentId || messageId === history.messages[history.currentId]?.parentId;

	// WebKit's content-visibility implementation has paint bugs that leave
	// on-screen messages blank (#26712), so skip virtualization there
	// iOS WebViews and home screen apps carry no Safari token, hence the vendor check
	const isWebKit =
		navigator.vendor === 'Apple Computer, Inc.' ||
		/^((?!chrome|android).)*safari/i.test(navigator.userAgent);
</script>

<div
	role="listitem"
	class="flex flex-col justify-between {$gisPortalVisible
		? 'px-1'
		: 'px-3.5'} mb-3 w-full {($settings?.widescreenMode ?? null)
		? 'max-w-full'
		: 'max-w-[58rem]'} mx-auto rounded-lg group message-listitem"
	class:message-virtualized={!isWebKit && !isCurrentTurn}
>
	{#if history.messages[messageId]}
		{#if history.messages[messageId].role === 'user'}
			<UserMessage
				{selectedModels}
				{user}
				{chatId}
				{history}
				{messageId}
				isFirstMessage={idx === 0}
				siblings={history.messages[messageId].parentId !== null
					? (history.messages[history.messages[messageId].parentId]?.childrenIds ?? [])
					: (Object.values(history.messages)
							.filter((message) => message.parentId === null)
							.map((message) => message.id) ?? [])}
				{gotoMessage}
				{showPreviousMessage}
				{showNextMessage}
				{editMessage}
				{deleteMessage}
				{allowDelete}
				{readOnly}
				{shareMode}
				{compactPreview}
				{editCodeBlock}
				{topPadding}
			/>
		{:else if compactPreview || (history.messages[history.messages[messageId].parentId]?.models?.length ?? 1) === 1}
			<ResponseMessage
				{chatId}
				{history}
				{messageId}
				{selectedModels}
				isLastMessage={messageId === history.currentId}
				siblings={history.messages[history.messages[messageId].parentId]?.childrenIds ?? []}
				{setInputText}
				{gotoMessage}
				{showPreviousMessage}
				{showNextMessage}
				{updateChat}
				{editMessage}
				{saveMessage}
				{rateMessage}
				{actionMessage}
				{submitMessage}
				{deleteMessage}
				{allowDelete}
				{allowToolApproval}
				{continueResponse}
				{regenerateResponse}
				{addMessages}
				{onToolCallResolved}
				{forkHandler}
				{readOnly}
				{compactPreview}
				{editCodeBlock}
				{topPadding}
				{onInsertToNote}
				{shareMode}
			/>
		{:else}
			{#key messageId}
				<MultiResponseMessages
					bind:history
					{chatId}
					{messageId}
					{selectedModels}
					isLastMessage={messageId === history?.currentId}
					{setInputText}
					{updateChat}
					{editMessage}
					{saveMessage}
					{rateMessage}
					{actionMessage}
					{submitMessage}
					{deleteMessage}
					{allowDelete}
					{allowToolApproval}
					{continueResponse}
					{regenerateResponse}
					{mergeResponses}
					{triggerScroll}
					{addMessages}
					{onToolCallResolved}
					{forkHandler}
					{readOnly}
					{compactPreview}
					{editCodeBlock}
					{topPadding}
					{onInsertToNote}
					{shareMode}
				/>
			{/key}
		{/if}
	{/if}
</div>

<style>
	/* Browser-native virtualization: skip rendering of off-screen messages
	   without destroying their component trees. Replaces the JS-based
	   culling that caused catastrophic mount/destroy thrashing. */
	.message-virtualized {
		content-visibility: auto;
		contain-intrinsic-size: auto 150px;
	}
</style>
